package com.shikshasetu.controller;
import com.shikshasetu.model.*;import com.shikshasetu.portal.*;import com.shikshasetu.repo.*;import com.shikshasetu.service.PortalAuditService;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController @RequestMapping("/api/my") public class StudentSelfController{
 private final PortalUserRepository users;private final StudentRepository students;private final StudentProgressRepository progress;private final PortalAuditService audit;private final AcademicRecordRepository academicRecords;
 public StudentSelfController(PortalUserRepository u,StudentRepository s,StudentProgressRepository p,PortalAuditService a,AcademicRecordRepository ar){users=u;students=s;progress=p;audit=a;academicRecords=ar;}
 public record ConsentRequest(boolean chatMonitoringConsent){}
 public record ProgressRequest(@DecimalMin("0.0") @DecimalMax("100.0") double attendance,@Min(0) int assignmentsDone,@Min(0) int assignmentsTotal,@Min(0) int problems,@DecimalMin("0.0") @DecimalMax("168.0") double hours,@Size(max=500) String note){}
 @PutMapping("/privacy-consent") @Transactional public Map<String,Object> updatePrivacyConsent(@RequestBody ConsentRequest request){PortalUser u=PortalAuthContext.require().user();boolean previous=u.isChatMonitoringConsent();u.setChatMonitoringConsent(request.chatMonitoringConsent());if(request.chatMonitoringConsent())u.setConsentAt(java.time.LocalDateTime.now());users.save(u);if(previous!=request.chatMonitoringConsent())audit.record(request.chatMonitoringConsent()?"CHAT_MONITORING_CONSENT_GRANTED":"CHAT_MONITORING_CONSENT_WITHDRAWN",u.getStudentId(),request.chatMonitoringConsent()?"Student enabled institutional chatbot monitoring":"Student withdrew chatbot monitoring consent");return Map.of("chatMonitoringConsent",u.isChatMonitoringConsent(),"consentAt",u.getConsentAt()==null?"":u.getConsentAt().toString(),"message",u.isChatMonitoringConsent()?"Chat companion access is enabled.":"Chat companion access is paused because monitoring consent was withdrawn.");}
 @GetMapping("/profile") public Map<String,Object> profile(){PortalUser u=PortalAuthContext.require().user();Student s=student(u);return Map.of("studentId",s.getId(),"studentCode",s.getStudentCode(),"fullName",s.getFullName(),"email",s.getEmail()==null?"":s.getEmail(),"attendance",s.getAttendance(),"internalMarks",s.getInternalMarks(),"assignmentsCompleted",s.getAssignmentsCompleted(),"previousFailures",s.getPreviousFailures(),"absences",s.getAbsences(),"aiMentorName",u.getAiMentorName()==null?"ShikshaSetu AI":u.getAiMentorName());}
 @GetMapping("/academic-records") public List<AcademicRecord> academicRecords(){return academicRecords.findByStudentIdOrderByRecordDateDescIdDesc(student(PortalAuthContext.require().user()).getId());}
 @GetMapping("/progress") public List<StudentProgress> myProgress(){return progress.findTop100ByStudentIdOrderByCreatedAtDesc(student(PortalAuthContext.require().user()).getId());}
 @PostMapping("/progress") @Transactional public StudentProgress saveProgress(@Valid @RequestBody ProgressRequest r){if(r.assignmentsDone()>r.assignmentsTotal())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Completed assignments cannot exceed total assignments");PortalUser u=PortalAuthContext.require().user();Student s=student(u);StudentProgress item=new StudentProgress(u.getInstitutionId(),s.getId(),u.getId(),r.attendance(),r.assignmentsDone(),r.assignmentsTotal(),r.problems(),r.hours(),r.note()==null?"":r.note().trim());audit.record("STUDENT_PROGRESS_SAVED",s.getId(),"Student submitted a progress check-in");return progress.save(item);}
 @PutMapping("/profile") @Transactional public Map<String,Object> updateProfile(@RequestBody Map<String,String> body){PortalUser u=PortalAuthContext.require().user();String name=body.get("fullName");if(name!=null){if(name.trim().length()<2||name.trim().length()>120)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Name must contain 2–120 characters");u.setFullName(name.trim());PortalUser ignored=users.save(u);Student s=student(u);s.setFullName(name.trim());students.save(s);}audit.record("STUDENT_PROFILE_UPDATED",u.getStudentId(),"Student updated profile details");return profile();}
 private Student student(PortalUser u){if(u.getStudentId()==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Student workspace has not been approved");return students.findById(u.getStudentId()).filter(x->Objects.equals(x.getInstitutionId(),u.getInstitutionId())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Student record not found"));}
}
